"""Tokenizer, syntax tree, and parser for minisql queries."""

import re

from .errors import QueryError

KEYWORDS = frozenset("""
    SELECT DISTINCT FROM WHERE GROUP BY HAVING ORDER ASC DESC LIMIT OFFSET
    AS AND OR NOT IS NULL IN BETWEEN LIKE TRUE FALSE
""".split())

AGGREGATES = frozenset(["COUNT", "SUM", "AVG", "MIN", "MAX"])

# Scalar functions: name -> (minimum arguments, maximum arguments or None).
SCALARS = {
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (1, None),
}

COMPARISONS = frozenset(["=", "!=", "<", "<=", ">", ">="])


# --- Tokens -----------------------------------------------------------------

class Token:
    """A token: ``kind`` is one of num, str, name, kw, op, or eof."""

    def __init__(self, kind, value, start, end):
        self.kind = kind
        self.value = value
        self.start = start
        self.end = end

    def __repr__(self):
        return "Token(%r, %r)" % (self.kind, self.value)


_TOKEN_RE = re.compile(r"""
    (?P<space>\s+)
  | (?P<num>[0-9]+\.[0-9]*|\.[0-9]+|[0-9]+)
  | (?P<name>[A-Za-z_][A-Za-z0-9_]*)
  | (?P<qname>"(?:[^"]|"")*")
  | (?P<str>'(?:[^']|'')*')
  | (?P<op><=|>=|<>|!=|\|\||[=<>+\-*/(),;])
""", re.VERBOSE)

_IDENT_CHAR = re.compile(r"[A-Za-z0-9_]")


def tokenize(sql):
    tokens = []
    pos = 0
    while pos < len(sql):
        m = _TOKEN_RE.match(sql, pos)
        if m is None:
            if sql[pos] in "'\"":
                raise QueryError("unterminated quoted text at position %d" % pos)
            raise QueryError("unexpected character %r at position %d" % (sql[pos], pos))
        kind = m.lastgroup
        text = m.group()
        start, pos = m.start(), m.end()
        if kind == "space":
            continue
        if kind == "num":
            if pos < len(sql) and _IDENT_CHAR.match(sql, pos):
                raise QueryError("invalid number at position %d" % start)
            value = float(text) if "." in text else int(text)
            tokens.append(Token("num", value, start, pos))
        elif kind == "name":
            upper = text.upper()
            if upper in KEYWORDS:
                tokens.append(Token("kw", upper, start, pos))
            else:
                tokens.append(Token("name", text, start, pos))
        elif kind == "qname":
            tokens.append(Token("qname", text[1:-1].replace('""', '"'), start, pos))
        elif kind == "str":
            tokens.append(Token("str", text[1:-1].replace("''", "'"), start, pos))
        else:
            tokens.append(Token("op", "!=" if text == "<>" else text, start, pos))
    tokens.append(Token("eof", None, len(sql), len(sql)))
    return tokens


# --- Syntax tree ------------------------------------------------------------

class Node:
    """An expression.  ``start`` and ``end`` locate its text in the query.

    ``key()`` gives a hashable value that is equal for two expressions that
    mean the same thing, used to match columns against GROUP BY expressions.
    """

    start = end = 0

    def children(self):
        return ()

    def walk(self):
        yield self
        for child in self.children():
            yield from child.walk()


class Literal(Node):
    def __init__(self, value):
        self.value = value

    def key(self):
        return ("lit", type(self.value).__name__, self.value)


class Column(Node):
    def __init__(self, name):
        self.name = name
        self.index = None  # set by resolve

    def key(self):
        return ("col", self.index)


class Unary(Node):
    """Unary minus or NOT."""

    def __init__(self, op, operand):
        self.op = op
        self.operand = operand

    def children(self):
        return (self.operand,)

    def key(self):
        return ("unary", self.op, self.operand.key())


class Binary(Node):
    """AND, OR, comparisons, and arithmetic."""

    def __init__(self, op, left, right):
        self.op = op
        self.left = left
        self.right = right

    def children(self):
        return (self.left, self.right)

    def key(self):
        return ("binary", self.op, self.left.key(), self.right.key())


class IsNull(Node):
    def __init__(self, operand, negated):
        self.operand = operand
        self.negated = negated

    def children(self):
        return (self.operand,)

    def key(self):
        return ("isnull", self.negated, self.operand.key())


class In(Node):
    def __init__(self, operand, items, negated):
        self.operand = operand
        self.items = items
        self.negated = negated

    def children(self):
        return (self.operand,) + tuple(self.items)

    def key(self):
        return ("in", self.negated) + tuple(c.key() for c in self.children())


class Between(Node):
    def __init__(self, operand, low, high, negated):
        self.operand = operand
        self.low = low
        self.high = high
        self.negated = negated

    def children(self):
        return (self.operand, self.low, self.high)

    def key(self):
        return ("between", self.negated) + tuple(c.key() for c in self.children())


class Like(Node):
    def __init__(self, operand, pattern, negated):
        self.operand = operand
        self.pattern = pattern
        self.negated = negated

    def children(self):
        return (self.operand, self.pattern)

    def key(self):
        return ("like", self.negated, self.operand.key(), self.pattern.key())


class Function(Node):
    """A scalar function call; ``name`` is upper case."""

    def __init__(self, name, args):
        self.name = name
        self.args = args

    def children(self):
        return tuple(self.args)

    def key(self):
        return ("func", self.name) + tuple(a.key() for a in self.args)


class Aggregate(Node):
    """An aggregate call; ``arg`` is None for ``COUNT(*)``."""

    def __init__(self, name, arg):
        self.name = name
        self.arg = arg

    def children(self):
        return () if self.arg is None else (self.arg,)

    def key(self):
        return ("agg", self.name, None if self.arg is None else self.arg.key())


class SelectColumn:
    def __init__(self, expr, alias):
        self.expr = expr
        self.alias = alias


class OrderItem:
    def __init__(self, expr, descending):
        self.expr = expr
        self.descending = descending


class Query:
    def __init__(self):
        self.distinct = False
        self.columns = None  # None for SELECT *
        self.table = None
        self.where = None
        self.group_by = []
        self.having = None
        self.order_by = []
        self.limit = None
        self.offset = 0


# --- Parser -----------------------------------------------------------------

def parse(sql):
    """Parse ``sql`` into a Query."""
    return _Parser(sql).query()


class _Parser:
    def __init__(self, sql):
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0

    # Token helpers

    @property
    def tok(self):
        return self.tokens[self.pos]

    def advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def at(self, kind, value=None):
        tok = self.tok
        return tok.kind == kind and (value is None or tok.value == value)

    def at_kw(self, *words):
        return self.tok.kind == "kw" and self.tok.value in words

    def accept(self, kind, value=None):
        if self.at(kind, value):
            return self.advance()
        return None

    def expect(self, kind, value=None):
        if not self.at(kind, value):
            wanted = value if value is not None else kind
            self.fail("expected %s" % wanted)
        return self.advance()

    def fail(self, message):
        tok = self.tok
        if tok.kind == "eof":
            found = "end of query"
        else:
            found = repr(self.sql[tok.start:tok.end])
        raise QueryError("syntax error: %s, found %s at position %d"
                         % (message, found, tok.start))

    def name(self):
        if self.tok.kind in ("name", "qname"):
            return self.advance().value
        self.fail("expected a name")

    def integer(self):
        tok = self.tok
        if tok.kind != "num" or not isinstance(tok.value, int):
            self.fail("expected an integer")
        return self.advance().value

    # Clauses

    def query(self):
        q = Query()
        self.expect("kw", "SELECT")
        q.distinct = bool(self.accept("kw", "DISTINCT"))
        if self.accept("op", "*"):
            q.columns = None
        else:
            q.columns = [self.select_column()]
            while self.accept("op", ","):
                q.columns.append(self.select_column())
        self.expect("kw", "FROM")
        q.table = self.name()
        if self.accept("kw", "WHERE"):
            q.where = self.expr()
        if self.accept("kw", "GROUP"):
            self.expect("kw", "BY")
            q.group_by = self.expr_list()
        if self.accept("kw", "HAVING"):
            q.having = self.expr()
        if self.accept("kw", "ORDER"):
            self.expect("kw", "BY")
            q.order_by = [self.order_item()]
            while self.accept("op", ","):
                q.order_by.append(self.order_item())
        if self.accept("kw", "LIMIT"):
            q.limit = self.integer()
            if self.accept("kw", "OFFSET"):
                q.offset = self.integer()
        self.accept("op", ";")
        if not self.at("eof"):
            self.fail("expected end of query")
        return q

    def select_column(self):
        expr = self.expr()
        alias = None
        if self.accept("kw", "AS"):
            alias = self.name()
        elif self.tok.kind in ("name", "qname"):
            alias = self.advance().value
        return SelectColumn(expr, alias)

    def order_item(self):
        expr = self.expr()
        descending = False
        if self.accept("kw", "DESC"):
            descending = True
        else:
            self.accept("kw", "ASC")
        return OrderItem(expr, descending)

    def expr_list(self):
        exprs = [self.expr()]
        while self.accept("op", ","):
            exprs.append(self.expr())
        return exprs

    # Expressions, lowest precedence first

    def spanned(self, node, start):
        node.start = start
        node.end = self.tokens[self.pos - 1].end
        return node

    def expr(self):
        return self.or_expr()

    def or_expr(self):
        start = self.tok.start
        left = self.and_expr()
        while self.accept("kw", "OR"):
            left = self.spanned(Binary("OR", left, self.and_expr()), start)
        return left

    def and_expr(self):
        start = self.tok.start
        left = self.not_expr()
        while self.accept("kw", "AND"):
            left = self.spanned(Binary("AND", left, self.not_expr()), start)
        return left

    def not_expr(self):
        start = self.tok.start
        if self.accept("kw", "NOT"):
            return self.spanned(Unary("NOT", self.not_expr()), start)
        return self.comparison()

    def comparison(self):
        start = self.tok.start
        left = self.additive()
        while True:
            if self.tok.kind == "op" and self.tok.value in COMPARISONS:
                op = self.advance().value
                left = Binary(op, left, self.additive())
            elif self.accept("kw", "IS"):
                negated = bool(self.accept("kw", "NOT"))
                self.expect("kw", "NULL")
                left = IsNull(left, negated)
            elif self.at_kw("NOT", "IN", "BETWEEN", "LIKE"):
                negated = bool(self.accept("kw", "NOT"))
                if self.accept("kw", "IN"):
                    self.expect("op", "(")
                    items = self.expr_list()
                    self.expect("op", ")")
                    left = In(left, items, negated)
                elif self.accept("kw", "BETWEEN"):
                    low = self.additive()
                    self.expect("kw", "AND")
                    left = Between(left, low, self.additive(), negated)
                elif self.accept("kw", "LIKE"):
                    left = Like(left, self.additive(), negated)
                else:
                    self.fail("expected IN, BETWEEN, or LIKE")
            else:
                return left
            self.spanned(left, start)

    def additive(self):
        start = self.tok.start
        left = self.multiplicative()
        while self.tok.kind == "op" and self.tok.value in ("+", "-", "||"):
            op = self.advance().value
            left = self.spanned(Binary(op, left, self.multiplicative()), start)
        return left

    def multiplicative(self):
        start = self.tok.start
        left = self.unary()
        while self.tok.kind == "op" and self.tok.value in ("*", "/"):
            op = self.advance().value
            left = self.spanned(Binary(op, left, self.unary()), start)
        return left

    def unary(self):
        start = self.tok.start
        if self.accept("op", "-"):
            return self.spanned(Unary("-", self.unary()), start)
        return self.primary()

    def primary(self):
        tok = self.tok
        start = tok.start
        if tok.kind in ("num", "str"):
            self.advance()
            return self.spanned(Literal(tok.value), start)
        if self.at_kw("NULL", "TRUE", "FALSE"):
            self.advance()
            value = {"NULL": None, "TRUE": True, "FALSE": False}[tok.value]
            return self.spanned(Literal(value), start)
        if self.accept("op", "("):
            node = self.expr()
            self.expect("op", ")")
            return self.spanned(node, start)
        if tok.kind == "name" and self.tokens[self.pos + 1].value == "(" \
                and self.tokens[self.pos + 1].kind == "op":
            return self.call()
        if tok.kind in ("name", "qname"):
            self.advance()
            return self.spanned(Column(tok.value), start)
        self.fail("expected an expression")

    def call(self):
        start = self.tok.start
        name_tok = self.advance()
        name = name_tok.value.upper()
        self.expect("op", "(")
        if name in AGGREGATES:
            if name == "COUNT" and self.accept("op", "*"):
                arg = None
            else:
                arg = self.expr()
            self.expect("op", ")")
            return self.spanned(Aggregate(name, arg), start)
        if name not in SCALARS:
            raise QueryError("unknown function %s" % name_tok.value)
        args = [] if self.at("op", ")") else self.expr_list()
        self.expect("op", ")")
        low, high = SCALARS[name]
        if len(args) < low or (high is not None and len(args) > high):
            raise QueryError("wrong number of arguments to %s" % name)
        return self.spanned(Function(name, args), start)

