            resolve(e, header)
            order.append(("expr", e, item.descending))
    order_exprs = [o[1] for o in order if o[0] == "expr"]

    # Aggregate placement.
    if query.where is not None:
        resolve(query.where, header)
        if has_aggregate(query.where):
            raise QueryError("aggregates can't be used in WHERE")
    for e in query.group_by:
        resolve(e, header)
        if has_aggregate(e):
            raise QueryError("aggregates can't be used in GROUP BY")
    if query.having is not None:
        resolve(query.having, header)
    later = exprs + order_exprs + ([query.having] if query.having is not None else [])
    for e in later:
        check_no_nested_aggregates(e)

    grouped = bool(query.group_by) or any(has_aggregate(e) for e in later)
    if grouped:
        group_keys = {e.key() for e in query.group_by}
        for e in later:
            check_grouped(e, group_keys)

    # FROM and WHERE.
    if query.where is not None:
        rows = [r for r in rows if evaluate(query.where, Context(r)) is True]

    # GROUP BY.
    if not grouped:
        contexts = [Context(r) for r in rows]
    elif not query.group_by:
        contexts = [Context(rows[0] if rows else None, rows)]
    else:
        groups = {}
        for r in rows:
            ctx = Context(r)
            key = tuple(value_key(evaluate(e, ctx)) for e in query.group_by)
            if key in groups:
                groups[key].rows.append(r)
            else:
                groups[key] = Context(r, [r])
        contexts = list(groups.values())

    # HAVING.
    if query.having is not None:
        contexts = [c for c in contexts if evaluate(query.having, c) is True]

    # SELECT, keeping the values ORDER BY needs.
    results = []
    for ctx in contexts:
        out = tuple(evaluate(e, ctx) for e in exprs)
        keys = tuple(out[o[1]] if o[0] == "output" else evaluate(o[1], ctx)
                     for o in order)
        results.append((out, keys))

    # DISTINCT.
    if query.distinct:
        seen = set()
        unique = []
        for out, keys in results:
            k = tuple(value_key(v) for v in out)
            if k not in seen:
                seen.add(k)
                unique.append((out, keys))
        results = unique

    # ORDER BY (stable).
    if order:
        directions = [o[2] for o in order]

        def cmp(a, b):
            for x, y, descending in zip(a[1], b[1], directions):
                c = compare_nulls_first(x, y)
                if c:
                    return -c if descending else c
            return 0

        results.sort(key=functools.cmp_to_key(cmp))

    # LIMIT and OFFSET.
    end = None if query.limit is None else query.offset + query.limit
    results = results[query.offset:end]

    return Result(names, [out for out, keys in results])


def query_text(query, node):
    return query.sql[node.start:node.end]

