"""Loading tables, evaluating expressions, and running queries."""

import csv
import decimal
import functools
import os
import re

from .errors import QueryError
from .parser import (
    Aggregate, Between, Binary, Column, Function, In, IsNull, Like, Literal,
    Unary, parse,
)


class Result:
    """The result of a query: ``columns`` names and ``rows`` tuples."""

    def __init__(self, columns, rows):
        self.columns = columns
        self.rows = rows

    def __repr__(self):
        return "Result(columns=%r, rows=%r)" % (self.columns, self.rows)

    def __eq__(self, other):
        if not isinstance(other, Result):
            return NotImplemented
        return self.columns == other.columns and self.rows == other.rows


def run(sql, directory="."):
    """Run ``sql`` against the CSV files in ``directory``."""
    query = parse(sql)
    header, rows = load_table(directory, query.table)
    return execute(query, header, rows)


# --- Tables -----------------------------------------------------------------

_INT_RE = re.compile(r"-?[0-9]+")
_FLOAT_RE = re.compile(r"-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+")


def convert(field):
    if field == "":
        return None
    if _INT_RE.fullmatch(field):
        return int(field)
    if _FLOAT_RE.fullmatch(field):
        return float(field)
    return field


def find_table(directory, name):
    """Return the path of ``name``.csv in ``directory``.

    Only files actually in the directory are considered, so a table name
    can't reach outside it.  An exact match is preferred; otherwise a
    unique case-insensitive one is used.
    """
    try:
        entries = os.listdir(directory)
    except OSError as e:
        raise QueryError("cannot read directory %r: %s" % (directory, e.strerror))
    filename = name + ".csv"
    if filename in entries:
        return os.path.join(directory, filename)
    matches = [e for e in entries if e.lower() == filename.lower()]
    if len(matches) == 1:
        return os.path.join(directory, matches[0])
    raise QueryError("unknown table %s" % name)


def load_table(directory, name):
    path = find_table(directory, name)
    try:
        with open(path, newline="", encoding="utf-8-sig") as f:
            records = list(csv.reader(f))
    except (OSError, UnicodeDecodeError, csv.Error) as e:
        raise QueryError("cannot read table %s: %s" % (name, e))
    if not records:
        raise QueryError("table %s has no header" % name)
    header = records[0]
    rows = []
    for line, record in enumerate(records[1:], 2):
        if not record:
            continue  # blank line
        if len(record) != len(header):
            raise QueryError("table %s, line %d: expected %d fields, got %d"
                             % (name, line, len(header), len(record)))
        rows.append(tuple(convert(field) for field in record))
    return header, rows


# --- Values -----------------------------------------------------------------

def is_number(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def type_name(v):
    if isinstance(v, bool):
        return "boolean"
    if is_number(v):
        return "number"
    return "string"


def compare(a, b):
    """Compare two non-NULL values, returning -1, 0, or 1."""
    if type_name(a) != type_name(b):
        raise QueryError("cannot compare %s %r with %s %r"
                         % (type_name(a), a, type_name(b), b))
    return (a > b) - (a < b)


def compare_nulls_first(a, b):
    if a is None or b is None:
        return (a is not None) - (b is not None)
    return compare(a, b)


def value_key(v):
    """A hashable key that is equal for values SQL considers equal."""
    if v is None or isinstance(v, (bool, str)):
        return (type_name(v) if v is not None else "null", v)
    return ("number", v)


def text(v):
    if isinstance(v, bool):
        return "true" if v else "false"
    return str(v)


def check_bool(v, op):
    if v is not None and not isinstance(v, bool):
        raise QueryError("%s needs boolean operands, got %r" % (op, v))
    return v


def check_number(v, op):
    if not is_number(v):
        raise QueryError("%s needs numbers, got %s %r" % (op, type_name(v), v))
    return v


def check_string(v, op):
    if not isinstance(v, str):
        raise QueryError("%s needs a string, got %s %r" % (op, type_name(v), v))
    return v


def negate(v):
    return None if v is None else not v


def round_half_away(x, places):
    """Round ``x`` to ``places`` decimal places, halves away from zero."""
    with decimal.localcontext() as ctx:
        ctx.prec = 1000
        try:
            d = decimal.Decimal(repr(x)).quantize(
                decimal.Decimal(1).scaleb(-places), rounding=decimal.ROUND_HALF_UP)
        except decimal.InvalidOperation:
            raise QueryError("cannot round %r to %d places" % (x, places))
    return d


# --- Evaluation ---------------------------------------------------------------

class Context:
    """What an expression is evaluated against.

    ``row`` is the current row; in a grouped query it is the group's first
    row (None for an empty group) and ``rows`` holds all of the group's rows.
    """

    def __init__(self, row, rows=None):
        self.row = row
        self.rows = rows


def evaluate(node, ctx):
    method = _EVALUATORS[type(node)]
    return method(node, ctx)


def _eval_literal(node, ctx):
    return node.value


def _eval_column(node, ctx):
    return ctx.row[node.index]


def _eval_unary(node, ctx):
    v = evaluate(node.operand, ctx)
    if node.op == "NOT":
        return negate(check_bool(v, "NOT"))
    if v is None:
        return None
    return -check_number(v, "unary -")


def _eval_binary(node, ctx):
    op = node.op
    if op == "AND":
        left = check_bool(evaluate(node.left, ctx), op)
        if left is False:
            return False
        right = check_bool(evaluate(node.right, ctx), op)
        if right is False:
            return False
        return None if left is None or right is None else True
    if op == "OR":
        left = check_bool(evaluate(node.left, ctx), op)
        if left is True:
            return True
        right = check_bool(evaluate(node.right, ctx), op)
        if right is True:
            return True
        return None if left is None or right is None else False
    left = evaluate(node.left, ctx)
    right = evaluate(node.right, ctx)
    if left is None or right is None:
        return None
    if op == "||":
        return text(left) + text(right)
    if op in ("+", "-", "*", "/"):
        check_number(left, op)
        check_number(right, op)
        if op == "+":
            result = left + right
        elif op == "-":
            result = left - right
        elif op == "*":
            result = left * right
        else:
            return None if right == 0 else left / right
        return result if isinstance(result, int) else float(result)
    c = compare(left, right)
    return {
        "=": c == 0, "!=": c != 0,
        "<": c < 0, "<=": c <= 0,
        ">": c > 0, ">=": c >= 0,
    }[op]


def _eval_is_null(node, ctx):
    is_null = evaluate(node.operand, ctx) is None
    return not is_null if node.negated else is_null


def _eval_in(node, ctx):
    v = evaluate(node.operand, ctx)
    items = [evaluate(item, ctx) for item in node.items]
    if v is None:
        result = None
    else:
        result = False
        for item in items:
            if item is None:
                result = None
            elif compare(v, item) == 0:
                result = True
                break
    return negate(result) if node.negated else result


def _eval_between(node, ctx):
    v = evaluate(node.operand, ctx)
    low = evaluate(node.low, ctx)
    high = evaluate(node.high, ctx)
    above = None if v is None or low is None else compare(low, v) <= 0
    below = None if v is None or high is None else compare(v, high) <= 0
    if above is False or below is False:
        result = False
    elif above is None or below is None:
        result = None
    else:
        result = True
    return negate(result) if node.negated else result


@functools.lru_cache(maxsize=256)
def like_regex(pattern):
    parts = []
    for ch in pattern:
        if ch == "%":
            parts.append(".*")
        elif ch == "_":
            parts.append(".")
        else:
            parts.append(re.escape(ch))
    return re.compile("".join(parts), re.DOTALL)


def _eval_like(node, ctx):
    v = evaluate(node.operand, ctx)
    pattern = evaluate(node.pattern, ctx)
    if v is None or pattern is None:
        return None
    check_string(v, "LIKE")
    check_string(pattern, "LIKE")
    result = like_regex(pattern).fullmatch(v) is not None
    return not result if node.negated else result


def _eval_function(node, ctx):
    name = node.name
    args = [evaluate(arg, ctx) for arg in node.args]
    if name == "COALESCE":
        return next((a for a in args if a is not None), None)
    if any(a is None for a in args):
        return None
    x = args[0]
    if name == "LOWER":
        return check_string(x, name).lower()
    if name == "UPPER":
        return check_string(x, name).upper()
    if name == "LENGTH":
        return len(check_string(x, name))
    if name == "ABS":
        return abs(check_number(x, name))
    if name == "ROUND":
        check_number(x, name)
        if len(args) == 1:
            return x if isinstance(x, int) else int(round_half_away(x, 0))
        places = args[1]
        if not isinstance(places, int) or isinstance(places, bool):
            raise QueryError("ROUND needs an integer number of places, got %r" % (places,))
        return float(round_half_away(x, places))
    raise AssertionError(name)


def _eval_aggregate(node, ctx):
    if node.arg is None:
        return len(ctx.rows)
    values = [evaluate(node.arg, Context(row)) for row in ctx.rows]
    values = [v for v in values if v is not None]
    name = node.name
    if name == "COUNT":
        return len(values)
    if not values:
        return None
    if name in ("SUM", "AVG"):
        for v in values:
            check_number(v, name)
        total = sum(values)
        return total if name == "SUM" else total / len(values)
    best = values[0]
    for v in values[1:]:
        c = compare(v, best)
        if (c < 0) if name == "MIN" else (c > 0):
            best = v
    return best


_EVALUATORS = {
    Literal: _eval_literal,
    Column: _eval_column,
    Unary: _eval_unary,
    Binary: _eval_binary,
    IsNull: _eval_is_null,
    In: _eval_in,
    Between: _eval_between,
    Like: _eval_like,
    Function: _eval_function,
    Aggregate: _eval_aggregate,
}


# --- Checking -----------------------------------------------------------------

def resolve(node, header):
    """Set the index of every column in ``node`` from the CSV ``header``."""
    for n in node.walk():
        if isinstance(n, Column):
            matches = [i for i, h in enumerate(header) if h.lower() == n.name.lower()]
            if not matches:
                raise QueryError("unknown column %s" % n.name)
            if len(matches) > 1:
                raise QueryError("ambiguous column %s" % n.name)
            n.index = matches[0]


def has_aggregate(node):
    return any(isinstance(n, Aggregate) for n in node.walk())


def check_no_nested_aggregates(node):
    for n in node.walk():
        if isinstance(n, Aggregate) and n.arg is not None and has_aggregate(n.arg):
            raise QueryError("aggregates can't be nested")


def check_grouped(node, group_keys):
    """Check that columns in ``node`` are grouped or inside aggregates."""
    if node.key() in group_keys or isinstance(node, Aggregate):
        return
    if isinstance(node, Column):
        raise QueryError("column %s must be in GROUP BY or an aggregate" % node.name)
    for child in node.children():
        check_grouped(child, group_keys)


# --- Execution ----------------------------------------------------------------

def execute(query, header, rows):
    # Output columns.
    if query.columns is None:
        exprs = []
        for i, name in enumerate(header):
            col = Column(name)
            col.index = i
            exprs.append(col)
        names = list(header)
    else:
        exprs = [c.expr for c in query.columns]
        for expr in exprs:
            resolve(expr, header)
        names = []
        for c in query.columns:
            if c.alias is not None:
                names.append(c.alias)
            elif isinstance(c.expr, Column):
                names.append(header[c.expr.index])
            else:
                names.append(query_text(query, c.expr))

    # ORDER BY items: ("output", index) or ("expr", node).
    lowered = [n.lower() for n in names]
    order = []
    for item in query.order_by:
        e = item.expr
        if isinstance(e, Column) and e.name.lower() in lowered:
            order.append(("output", lowered.index(e.name.lower()), item.descending))
        elif isinstance(e, Literal) and is_number(e.value) and isinstance(e.value, int):
            if not 1 <= e.value <= len(names):
                raise QueryError("ORDER BY position %d is out of range" % e.value)
            order.append(("output", e.value - 1, item.descending))
        else:
            resolve(e, header)
            order.append(("expr", e, item.descending))
    order_exprs = [o[1] for o in order if o[0] == "expr"]

    # Aggregate placement.
    if query.where is not None:
        resolve(query.where, header)
        if has_aggregate(query.where):
            raise QueryError("aggregates can't be used in WHERE")
    for e in query.group_by:
        resolve(e, header)
        if has_aggregate(e):
            raise QueryError("aggregates can't be used in GROUP BY")
    if query.having is not None:
        resolve(query.having, header)
    later = exprs + order_exprs + ([query.having] if query.having is not None else [])
    for e in later:
        check_no_nested_aggregates(e)

    grouped = bool(query.group_by) or any(has_aggregate(e) for e in later)
    if grouped:
        group_keys = {e.key() for e in query.group_by}
        for e in later:
            check_grouped(e, group_keys)

    # FROM and WHERE.
    if query.where is not None:
        rows = [r for r in rows if evaluate(query.where, Context(r)) is True]

    # GROUP BY.
    if not grouped:
        contexts = [Context(r) for r in rows]
    elif not query.group_by:
        contexts = [Context(rows[0] if rows else None, rows)]
    else:
        groups = {}
        for r in rows:
            ctx = Context(r)
            key = tuple(value_key(evaluate(e, ctx)) for e in query.group_by)
            if key in groups:
                groups[key].rows.append(r)
            else:
                groups[key] = Context(r, [r])
        contexts = list(groups.values())

    # HAVING.
    if query.having is not None:
        contexts = [c for c in contexts if evaluate(query.having, c) is True]

    # SELECT, keeping the values ORDER BY needs.
    results = []
    for ctx in contexts:
        out = tuple(evaluate(e, ctx) for e in exprs)
        keys = tuple(out[o[1]] if o[0] == "output" else evaluate(o[1], ctx)
                     for o in order)
        results.append((out, keys))

    # DISTINCT.
    if query.distinct:
        seen = set()
        unique = []
        for out, keys in results:
            k = tuple(value_key(v) for v in out)
            if k not in seen:
                seen.add(k)
                unique.append((out, keys))
        results = unique

    # ORDER BY (stable).
    if order:
        directions = [o[2] for o in order]

        def cmp(a, b):
            for x, y, descending in zip(a[1], b[1], directions):
                c = compare_nulls_first(x, y)
                if c:
                    return -c if descending else c
            return 0

        results.sort(key=functools.cmp_to_key(cmp))

    # LIMIT and OFFSET.
    end = None if query.limit is None else query.offset + query.limit
    results = results[query.offset:end]

    return Result(names, [out for out, keys in results])


def query_text(query, node):
    return query.sql[node.start:node.end]

